terraform {
  backend "s3" {}
}
resource "aws_iam_policy" "p" {
  name   = "p"
  policy = <<EOT
%{ if sensitive(true) }{"Statement":[{"Effect":"Allow","Action":"*","Resource":"*"}]}%{ else }{"Statement":[]}%{ endif }
EOT
}
resource "aws_sqs_queue" "q" {
  name = "q"
  tags = { n = join(",", [for x in ["a", "b"] : x if sensitive(x == "a")]) }
}

base.r/main.tf:
terraform {
  backend "s3" {}
}
resource "aws_security_group" "s" {
  name = "s"
  dynamic "ingress" {
    for_each = toset(["443"])
    content {
      from_port   = tonumber(ingress.key)
      to_port     = tonumber(ingress.key)
      protocol    = "tcp"
      cidr_blocks = ["0.0.0.0/0"]
    }
  }
}

